cn as (select d.*, trim(regexp_replace(lower(translate(d.nome_cliente,'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇç','AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCc')),'[^a-z0-9]+',' ','g')) n,
