m as (select a.n alvo,a.uf,a.cid,c.cnpj,c.telefone_mercos tm,coalesce(nullif(c.email_manual,''),nullif(c.email_mercos,''),nullif(c.email_tiny,''),nullif(c.email_neofin,'')) em,
 case when nullif(c.email_manual,'') is not null then 'manual' when nullif(c.email_mercos,'') is not null then 'Mercos' when nullif(c.email_tiny,'') is not null then 'Tiny' when nullif(c.email_neofin,'') is not null then 'Neofin' end ef,
